export function createHalloweenUI({getActive,focus,persist,fit,togglePause,isRunning}){
 const style=document.createElement('link');style.rel='stylesheet';style.href='/simulations/suburban/ui.css';document.head.append(style);
 const back=document.createElement('a');back.id='halloween-back';back.href='/sandbox';back.textContent='← Sandbox';document.querySelector('header').prepend(back);
 const panel=document.createElement('aside');panel.id='halloween-panel';panel.setAttribute('aria-label','Halloween choices');document.body.append(panel);
 const sample=new URLSearchParams(location.search).get('sample');let mode=sample==='journal'?'journal':'command';
 panel.innerHTML=`<div class="halloween-heading"><strong>Halloween walk</strong><select aria-label="HUD treatment" id="halloween-treatment"><option value="command">A · Field command</option><option value="journal">B · Night journal</option></select></div><p id="halloween-phase"></p><div id="halloween-party">Kit · Milo · June</div><div id="halloween-resources"></div><p id="halloween-near"></p><div class="halloween-actions"><button data-action="rise">Night of the Living Dead</button><button data-action="continue">Continue walk</button><button data-action="supplies">Seek supplies</button><button data-action="retreat">Retreat to lit porch</button><button data-action="advance">Advance toward horde</button><button data-action="confront">Use signal · −1 resolve</button><button data-action="battery">Fit battery · −1 battery</button></div><details><summary>Camera &amp; playback</summary><div class="halloween-actions"><button data-action="overview">Whole neighborhood</button><button data-action="pause">Pause / resume</button><button data-action="focus">Find party</button><button data-action="cemetery">See cemetery</button><button data-action="horde">Find horde</button></div></details><details open><summary>Choose next hex</summary><div id="halloween-hexes"></div></details><details><summary>Walk journal</summary><ol id="halloween-log"></ol></details><details><summary>Sources &amp; scope</summary><p>Reference-inspired, not an exact reconstruction. Public <a href="https://www.7shermanplace.com/" target="_blank" rel="noopener">Sherman Place photography</a> verifies pale clapboard, white trim, planted garden, deck and pergola. The <a href="https://www.coldwellbankerhomes.com/ma/winchester/7-sherman-pl-7/pid_73748204/" target="_blank" rel="noopener">public listing</a> describes a cul-de-sac and private garage.</p><p>Parcel boundaries, home count, street dimensions, adjacent hexes and cemetery location are fictional. No resident identities are used. Normal metres; shared stock people and trees with an architectural house kit. Inspired by <a href="https://www.dota2.com/700/hud/?l=english" target="_blank" rel="noopener">Dota’s readable action costs</a> and <a href="https://11bitstudios.com/games/this-war-of-mine/" target="_blank" rel="noopener">This War of Mine’s civilian scarcity</a>: Command emphasizes proximity/equipment; Journal emphasizes scarce supplies and consequential choices. Both operate the same saved simulation.</p><p>Implemented: connected walking, finite porch treats and supply cache, batteries, light, resolve, diversion and retreat. No household economy, weapons, injury or full combat model. Zombies preserve fictional grave identities; cemetery supports linked deceased records but none are supplied here.</p></details>`;
 const q=s=>panel.querySelector(s);q('#halloween-treatment').value=mode;
 function setMode(){panel.dataset.treatment=mode;if(new URLSearchParams(location.search).get('family')!=='suburban'&&document.body.dataset.family!=='suburban')return;const url=new URL(location.href);url.searchParams.set('sample',mode);history.replaceState(null,'',url);}
 q('#halloween-treatment').onchange=e=>{mode=e.target.value;setMode();};setMode();
 panel.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-hex]');if(!b)return;const a=getActive();if(!a)return;const act=b.dataset.action;if(act==='overview')fit();else if(act==='pause')togglePause();else if(b.dataset.hex)a.sim.choose('move',b.dataset.hex);else if(act==='focus')focus('party');else if(act==='cemetery')focus('cemetery');else if(act==='horde')focus('horde');else if(act==='rise'){a.sim.rise();focus('cemetery');}else a.sim.choose(act);persist();update();});
 q('#halloween-hexes').innerHTML=[['road210','Close'],['road140','Supply corner'],['road70','Alder lane'],['road35','Cemetery approach']].map(([id,label])=>`<button data-hex="${id}">${label}</button>`).join('');
 let previousPhase;
 function update(){const a=getActive();panel.hidden=!a;if(!a)return;const s=a.sim.state,n=a.sim.proximity();if(previousPhase==='trick-or-treat'&&s.phase==='rising')focus('cemetery');previousPhase=s.phase;q('#halloween-phase').textContent=s.escaped?'Safe at the lit porch':!isRunning()?'Playback paused':s.choice?'Paused for your choice':s.phase==='trick-or-treat'?'Trick-or-treating':s.phase==='rising'?'Graves stirring…':s.phase==='retreat'?'Returning to shelter':'Moving through the night';q('#halloween-resources').innerHTML=[[s.candy,'Treats'],[s.batteries,'Batteries'],[Math.round(s.light)+'%','Light'],[s.resolve+'/3','Resolve'],[s.signal,'Signals']].map(([n,label])=>`<span><b>${n}</b><small>${label}</small></span>`).join('');q('#halloween-near').textContent=Number.isFinite(n)?`${a.event.state.raised.length} raised · nearest ${Math.round(n)} m away`:'Cemetery quiet · three hexes from the close';q('[data-action=pause]').textContent=isRunning()?'Pause simulation':'Resume simulation';q('[data-action=rise]').disabled=s.phase!=='trick-or-treat';q('[data-action=battery]').disabled=!s.batteries||s.light>=100||s.escaped;q('[data-action=confront]').disabled=!s.signal||['trick-or-treat','rising'].includes(s.phase)||s.escaped;for(const b of panel.querySelectorAll('[data-hex],[data-action=advance],[data-action=supplies],[data-action=retreat],[data-action=continue]'))b.disabled=s.escaped||(['trick-or-treat','rising'].includes(s.phase)&&b.dataset.action!=='continue')||(s.resolve===0&&b.dataset.action!=='retreat');q('[data-action=supplies]').disabled=s.supplyTaken||s.escaped||['trick-or-treat','rising'].includes(s.phase);q('#halloween-log').replaceChildren(...s.log.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));document.querySelector('canvas').dataset.halloween=JSON.stringify({...s,cemetery:undefined,proximity:Number.isFinite(n)?n:null,raised:a.event.state.raised.length});}
 return {update};
}
